'use strict';
(()=>{
const $=id=>document.getElementById(id),menu=$('main-menu'),intro=$('intro-cinema'),video=$('intro-video'),film=document.querySelector('.intro-film'),status=$('menu-status');
if(!menu)return;
const introSlot=menu.querySelector('.menu-video-slot');if(introSlot)introSlot.innerHTML='<span>PREMISA + PRÓLOGO NARRADO</span><b>Cuando las campanas callan</b><small>Lee la premisa y luego acompaña a Elara, Ordan, Iria y Darien en la secuencia de apertura.</small>';
const premise=`<span class="menu-kicker">PREMISA · CENIZAS DEL UMBRAL</span><h2 id="intro-title">Cuando las campanas callan</h2><p>Durante trece años, las campanas de Valdara han guardado silencio. Una noche, una carta sellada con ceniza llega a tus manos; la ceniza no se enfría y el sello pertenece a la Vigilia, una orden que juró proteger un umbral que nadie puede ver.</p><p>Elara vigila el puente. Ordan reconoce el sello. Iria sigue huellas hacia el bosque y Darien ha desaparecido entre los registros de la Vigilia. La carta anuncia que alguien intenta abrir el Umbral desde el otro lado.</p><p>Tu personaje deberá cruzar Valdara, reunir a quienes aún recuerdan la verdad y decidir qué se salva cuando el pasado empieza a responder.</p><button id="start-intro-video" class="menu-primary" type="button">Ver el prólogo narrado</button>`;
const introCopy=document.querySelector('.intro-copy');if(introCopy)introCopy.innerHTML=`<div id="intro-premise" class="intro-premise">${premise}</div>`;
function hasSave(){try{const bridge=window.CenizasBridge;if(bridge?.hasSave)return bridge.hasSave();const c=JSON.parse(localStorage.getItem('cenizas-character-v1')||'null'),p=JSON.parse(localStorage.getItem('cenizas-valdara-v1')||'null');return Boolean(c?.name?.trim()&&c.race&&c.class&&c.subclass&&c.gender&&p&&Number.isInteger(p.stage));}catch{return false}}
function refresh(){const button=$('continue-game'),saved=hasSave();button.disabled=!saved;button.setAttribute('aria-disabled',String(!saved));if(!saved)status.textContent='No hay una partida guardada todavía.';else status.textContent='Partida encontrada en este dispositivo.';}
function closeMenu(){menu.dataset.active='false';menu.setAttribute('aria-hidden','true');}
function showIntro(done){let finished=false,started=false;const finish=()=>{if(finished)return;finished=true;clearTimeout(timer);video.onended=null;video.onerror=null;video.pause?.();intro.hidden=true;intro.setAttribute('aria-hidden','true');intro.dataset.stage='closed';film.hidden=false;intro.style.gridTemplateRows='';introCopy.style.alignSelf='';introCopy.style.padding='';film.classList.remove('video-ready');window.CenizasMusic?.set('exploration');done();};const startVideo=()=>{if(started||finished)return;started=true;intro.dataset.stage='video';film.hidden=false;intro.style.gridTemplateRows='';introCopy.style.alignSelf='';introCopy.style.padding='';introCopy.innerHTML='<span class="menu-kicker">PRÓLOGO NARRADO · LA CARTA SELLADA</span><h2 id="intro-title">Antes de cruzar el puente</h2><p>Las campanas de Valdara callaron hace trece años. Esta noche, una carta cubierta de ceniza vuelve a llamar a la puerta.</p><p>Observa la secuencia. Al terminar, crearás a quien cruzará el Umbral.</p><button id="skip-intro" class="menu-secondary" type="button">Continuar al creador</button>';const skip=$('skip-intro');if(skip)skip.onclick=finish;video.currentTime=0;video.load?.();const ready=()=>film.classList.add('video-ready');video.onloadeddata=ready;video.oncanplay=ready;video.onerror=()=>film.classList.remove('video-ready');video.onended=finish;video.play().catch(()=>{});window.CenizasMusic?.enable?.();window.CenizasMusic?.set('intro');};const timer=setTimeout(finish,60000);intro.hidden=false;intro.setAttribute('aria-hidden','false');intro.dataset.stage='premise';film.hidden=true;intro.style.gridTemplateRows='1fr';introCopy.style.alignSelf='center';introCopy.style.padding='clamp(28px,8vw,90px)';film.classList.remove('video-ready');video.pause?.();const start=$('start-intro-video');if(start)start.onclick=startVideo;}
function newGame(){closeMenu();showIntro(()=>window.CenizasBridge?.startNew?.());}
function continueGame(){closeMenu();window.CenizasBridge?.continueGame?.();}
$('new-game').onclick=newGame;$('continue-game').onclick=continueGame;$('exit-game').onclick=()=>{status.textContent='Puedes cerrar esta pestaña cuando quieras. Tu progreso guardado permanecerá en este dispositivo.';try{window.close();}catch{}};
refresh();window.CenizasMenu={refresh,showIntro};window.addEventListener('storage',refresh);window.addEventListener('pageshow',refresh);
})();
